import "io" for Directory

// Ensure clean state
var cleanup = Fiber.new { Directory.delete("dir_exists_test2.temp") }
cleanup.try()
Directory.create("dir_exists_test2.temp")
// Creating again should error (EEXIST)
var fi = Fiber.new { Directory.create("dir_exists_test2.temp") }
fi.try()
System.print(fi.error != null) // expect: true
Directory.delete("dir_exists_test2.temp")
